# frozen_string_literal: true
require "test_helper"

# Checks that fields generated by our macros behave the same way on execute_next as on the original engine
class ExecutionNextMacroFieldsTest < ActiveSupport::TestCase
  include ExecutionEngineComparisonHelper

  PERSONAL_INFO_SELECTION =
    "accepted_clickwrap_agreement address birth_date city country ical_secret mobile_phone state zipcode"

  let(:convention) { create(:convention) }
  let(:viewer) { create(:user_con_profile, convention:) }
  # For records that an ordinary attendee isn't allowed to read at all
  let(:admin) { create(:user_con_profile, convention:, user: create(:site_admin)) }

  def context_for(profile, **attrs)
    -> { ActiveSupport::TestCase::TestGraphqlContext.with_user_con_profile(UserConProfile.find(profile.id), **attrs) }
  end

  describe "personal info fields" do
    let(:subject_profile) do
      create(:user_con_profile, convention:, address: "123 Main St", city: "Springfield", mobile_phone: "5551234")
    end

    def personal_info_seen_by(profile)
      assert_engines_agree(
        Types::UserConProfileType,
        PERSONAL_INFO_SELECTION,
        -> { UserConProfile.find(subject_profile.id) },
        context_for(profile)
      )
    end

    it "shows them to the person they belong to" do
      data = personal_info_seen_by(subject_profile)

      assert_equal "123 Main St", data["address"]
      assert_equal "5551234", data["mobile_phone"]
    end

    it "hides them from other attendees who can see the rest of the profile" do
      # Team members can have a bio, which makes their profile readable by everyone
      create(:team_member, user_con_profile: subject_profile, event: create(:event, convention:))

      data = personal_info_seen_by(viewer)

      assert_equal [nil], data.values.uniq
    end
  end

  it "resolves registration policy bucket flags" do
    bucket = create(:registration_policy_bucket, slots_limited: true, anything: false, not_counted: true)

    data =
      assert_engines_agree(
        Types::RegistrationPolicyBucketType,
        "anything expose_attendees not_counted slots_limited",
        -> { RegistrationPolicyBucket.find(bucket.id) },
        context_for(viewer)
      )

    assert_equal(
      { "anything" => false, "expose_attendees" => false, "not_counted" => true, "slots_limited" => true },
      data
    )
  end

  it "resolves pagination entries" do
    coupon = create(:coupon, convention:)

    data =
      assert_engines_agree(
        Types::CouponsPaginationType,
        "entries { id }",
        -> { Coupon.where(id: coupon.id) },
        context_for(admin)
      )

    assert_equal [{ "id" => coupon.id.to_s }], data["entries"]
  end

  # These three come from the request rather than from the object being queried
  describe "fields that ContextAccessors resolves" do
    let(:other_convention) { create(:convention) }

    it "returns the request's convention for a coupon or ticket" do
      coupon = create(:coupon, convention: other_convention)
      ticket = create(:ticket, user_con_profile: create(:user_con_profile, convention: other_convention))

      { Types::CouponType => coupon, Types::TicketType => ticket }.each do |type, record|
        data = assert_engines_agree(type, "convention { id }", -> { record.class.find(record.id) }, context_for(admin))

        assert_equal convention.id.to_s, data.dig("convention", "id")
      end
    end

    it "returns the request's pending order for any profile" do
      order = create(:order, user_con_profile: admin)

      data =
        assert_engines_agree(
          Types::UserConProfileType,
          "current_pending_order { id }",
          -> { create(:user_con_profile, convention:) },
          context_for(admin, current_pending_order: order)
        )

      assert_equal order.id.to_s, data.dig("current_pending_order", "id")
    end

    it "returns the request's profile for signup constraints" do
      data =
        assert_engines_agree(
          Types::UserSignupConstraintsType,
          "user_con_profile { id }",
          -> { UserSignupConstraints.new(create(:user_con_profile, convention:)) },
          context_for(admin)
        )

      assert_equal admin.id.to_s, data.dig("user_con_profile", "id")
    end
  end
end
